#!/usr/bin/env node
/*
 * tools/build.js — src/*.js 엔진 모듈을 브라우저용 web/engine.js 하나로 합칩니다.
 *   node tools/build.js          → web/engine.js, bin/main.js, bin/test_runner.js 생성
 *   node tools/build.js --clean  → bin/ 삭제
 * GitHub Pages 배포(.github/workflows/pages.yml)에서도 이 스크립트를 실행합니다.
 */
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const ORDER = ['math_ops.js', 'stats.js', 'parser.js', 'payroll.js', 'checklist.js', 'workers.js', 'backup.js', 'xlsx.js', 'reports.js'];
const HEADER =
  '/* AUTO-GENERATED by tools/build.js — 직접 수정하지 마세요.\n' +
  ' * 원본: src/*.js  →  수정 후 `make web` 또는 `npm run build` 실행\n' +
  ' * 브라우저 내장 엔진: window.AlbaEngine (서버 없이 100% 동일 계산)\n' +
  ' */\n';

function version() {
  return JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8')).version;
}

function bundle() {
  return HEADER + ORDER.map((f) => {
    const src = fs.readFileSync(path.join(ROOT, 'src', f), 'utf8').replace(/^\uFEFF/, '').trim();
    return '\n/* ===== src/' + f + ' ===== */\n' + src + '\n';
  }).join('') + "\n/* ===== 버전 (package.json 의 version) ===== */\n;(typeof window !== 'undefined' ? window : globalThis).ALBA_VERSION = '" + version() + "';\n";
}

function build(opts) {
  const quiet = opts && opts.quiet;
  const out = path.join(ROOT, 'web', 'engine.js');
  fs.writeFileSync(out, bundle(), 'utf8');

  const bin = path.join(ROOT, 'bin');
  fs.mkdirSync(bin, { recursive: true });
  fs.writeFileSync(path.join(bin, 'main.js'),
    "#!/usr/bin/env node\n'use strict';\nrequire('../src/main.js').main(process.argv);\n", 'utf8');
  fs.writeFileSync(path.join(bin, 'test_runner.js'),
    "#!/usr/bin/env node\n'use strict';\nconst { spawnSync } = require('child_process');\nconst path = require('path');\n" +
    "let code = 0;\nfor (const t of ['test_main.js', 'test_cloud.js', 'test_server.js']) {\n" +
    "  const r = spawnSync(process.execPath, [path.join(__dirname, '..', 'tests', t)], { stdio: 'inherit' });\n" +
    "  if (r.status !== 0) code = 1;\n}\nprocess.exit(code);\n", 'utf8');

  if (!quiet) console.log('[build] web/engine.js, bin/main.js, bin/test_runner.js 생성 완료');
  return out;
}

function clean() {
  fs.rmSync(path.join(ROOT, 'bin'), { recursive: true, force: true });
  console.log('[clean] bin/ 삭제 완료 (web/engine.js 는 GitHub Pages 배포용으로 유지)');
}

if (require.main === module) {
  if (process.argv.includes('--clean')) clean();
  else build();
}

module.exports = { build, bundle, clean, ORDER };

